use micaforge_core::Error;

/// Default page size for list endpoints that do not ask for one.
pub const DEFAULT_LIMIT: i64 = 50;

/// Hard ceiling on a page size.
///
/// A list endpoint is a management surface, not an export. Anything that
/// genuinely needs every row uses the CSV export, which streams.
pub const MAX_LIMIT: i64 = 500;

/// Clamp a caller's page size into something a single query should return.
pub fn clamp_limit(limit: Option<i64>) -> i64 {
    limit.unwrap_or(DEFAULT_LIMIT).clamp(1, MAX_LIMIT)
}

/// Turn "no row" into a `404` that names what was missing.
///
/// `sqlx::Error::RowNotFound` already maps to `NotFound`, but only for
/// `fetch_one`. Repository getters use `fetch_optional` so that "absent" is a
/// value rather than an error, and this is where that value becomes the error
/// the HTTP layer wants, with a message that says which resource.
pub(crate) fn or_missing<T>(row: Option<T>, what: &str) -> micaforge_core::Result<T> {
    row.ok_or_else(|| Error::not_found(what.to_string()))
}
